structure.mermaidSource:
flowchart TD
  start(["Forma Verbal em Contexto de Infinitivo"]) --> proc_antepor["Antepor a Fórmula no Rascunho\n(PARA) + Pronome Reto + Infinitivo"]
  proc_antepor --> dec_num{"Qual é o número gramatical do sujeito?"}
  dec_num -- "Singular (eu, tu, ele)" --> dec_sing{"Qual a pessoa do singular?"}
  dec_num -- "Plural (nós, vós, eles)" --> dec_plur{"Qual a pessoa do plural?"}
  dec_sing -- "1ª ou 3ª pessoa (eu / ele)" --> res_sing_1_3["1ª ou 3ª Pessoa Singular\nDNP = Ø (Para eu/ele dedicar-Ø)"]
  dec_sing -- "2ª pessoa (tu)" --> res_sing_2["2ª Pessoa Singular\nDNP = -es (Para tu dedicar-es)"]
  dec_plur -- "1ª pessoa (nós)" --> res_plur_1["1ª Pessoa Plural\nDNP = -mos (Para nós dedicar-mos)"]
  dec_plur -- "2ª pessoa (vós)" --> res_plur_2["2ª Pessoa Plural\nDNP = -des (Para vós dedicar-des)"]
  dec_plur -- "3ª pessoa (eles)" --> res_plur_3["3ª Pessoa Plural\nDNP = -em (Para eles dedicar-em)"]

flowchart TD
  start(["Item de Prova: Estrutura Morfológica Completa"]) --> proc_quadro["Construir Quadro no Rascunho\n(Colunas: RAD | VT | DMT | DNP)"]
  proc_quadro --> proc_esquartejar["Segmentar Elementos Mórficos da Alternativa"]
  proc_esquartejar --> dec_rad{"Apresenta Radical (RAD) íntegro?"}
  dec_rad -- "Não" --> res_desc_rad["Descartar Alternativa\n(RAD ausente/nulo)"]
  dec_rad -- "Sim" --> dec_vt{"Apresenta Vogal Temática (VT) expressa?"}
  dec_vt -- "Não" --> res_desc_vt["Descartar Alternativa\n(VT = Ø ou absorvida)"]
  dec_vt -- "Sim" --> dec_dmt{"Apresenta Desinência Modo-Temporal (DMT) expressa?"}
  dec_dmt -- "Não" --> res_desc_dmt["Descartar Alternativa\n(DMT = Ø)"]
  dec_dmt -- "Sim" --> dec_dnp{"Apresenta Desinência Número-Pessoal (DNP) explícita?"}
  dec_dnp -- "Não" --> res_desc_dnp["Descartar Alternativa\n(DNP = Ø)"]
  dec_dnp -- "Sim" --> res_gabarito["Gabarito Confirmado\nEstrutura Quaternária Completa (RAD + VT + DMT + DNP)"]
